  "update.afterBackupHint": "Τραβά την εικόνα και αναδημιουργεί αυτό το κοντέινερ αμέσως μετά από ένα επιτυχημένο αντίγραφο ασφαλείας, ώστε να έχετε πάντα πρώτα ένα φρέσκο σημείο επαναφοράς. Εκτελείται τη στιγμή του αντιγράφου ασφαλείας (τα αντίγραφα ασφαλείας εκτελούνται το ένα μετά το άλλο), όχι σε καθορισμένη ώρα. Για ενημερώσεις με σταθερό πρόγραμμα, βάσει έκδοσης, δείτε το ShipLog.",
  "update.followsSchedule": "Όπως ορίζεται στις Ρυθμίσεις › Χρονοδιάγραμμα",
  "update.ownChoice": "Δική επιλογή",
  "update.useDefault": "Ακολούθηση προεπιλογής",
  "update.afterBackupOrphans":
    "Το Docker κρατά την εικόνα στην οποία έτρεχε πριν το container, τώρα χωρίς ετικέτα, και το Unraid την εμφανίζει ως ορφανή εικόνα. Είναι το φυσιολογικό υπόλειμμα μιας επιτυχημένης ενημέρωσης, όχι σημάδι αποτυχίας, και είναι ακριβώς αυτό που χρειάζεται μια γρήγορη επιστροφή στην προηγούμενη εικόνα. Αν δεν θέλετε να την κρατήσετε, ο διακόπτης «Αφαίρεση του παλιού image μετά από ενημέρωση» στις Ρυθμίσεις, Χρονοδιάγραμμα, Ενημερώσεις μετά το αντίγραφο ασφαλείας διαγράφει την αντικατασταθείσα εικόνα αμέσως μετά την ενημέρωση.",
