  "run.recentTitle": "Πρόσφατες εκτελέσεις",
  "breakdown.title": "Μέγεθος ανά φάκελο",
  "breakdown.hint": "Τι πιάνει χώρο στο νεότερο αντίγραφο ασφαλείας, το μεγαλύτερο πρώτο, και πόσο από αυτό έφερε νέο ή αλλαγμένο το τελευταίο αντίγραφο. Ένα αλλαγμένο αρχείο μετράει με όλο του το μέγεθος, γιατί το restic δεν λέει πόσο άλλαξε. Τα μεγέθη είναι μεγέθη αρχείων πριν από την αφαίρεση διπλοτύπων και τη συμπίεση. Το BombVault τα διαβάζει από το ευρετήριο του αποθετηρίου χωρίς να διαβάσει τα αρχεία και τα ενημερώνει μετά από κάθε αντίγραφο.",
  "breakdown.running": "Υπολογίζεται…",
