  // Settings
  "settings.title": "Ρυθμίσεις",
  "settings.encryptionPasswordWhere":
    "Αυτόν τον κωδικό δεν τον πληκτρολογείτε ποτέ: το BombVault τον παράγει από το APP_KEY σε κάθε κλήση. Η ίδια η τιμή βρίσκεται στο κιτ ανάκτησής σας, ως ο παραγόμενος κωδικός restic, και αυτήν χρειάζεστε για να τρέξετε restic με το χέρι σε ένα αποθετήριο.",
  "settings.encryptionHint":
    "Η κρυπτογράφηση καθορίζεται ανά αποθετήριο κατά τη δημιουργία του, οπότε αυτή η ρύθμιση αποφασίζει μόνο για νέο αποθετήριο. Για ένα που υπάρχει ήδη, το BombVault διαβάζει τον τρόπο από το ίδιο το αποθετήριο. Δείτε τη σελίδα Επαναφορά. Η αλλαγή του απέναντι σε υπάρχον αποθετήριο απλώς εμποδίζει το restic να το ανοίξει.",
  "settings.pathsHint": "Σχετικές υποδιαδρομές κάτω από τη ρίζα προσάρτησης του host ({root}). Κάντε κλικ στο Περιήγηση για να πλοηγηθείτε στους καταλόγους, ή πληκτρολογήστε μια διαδρομή απευθείας.",
