  "settings.dbDumpsHint": "Πριν από κάθε αντίγραφο ασφαλείας, τα αναγνωρισμένα κοντέινερ PostgreSQL, MySQL και MariaDB λαμβάνονται ως δικά τους σημεία επαναφοράς. Εδώ το κλείνετε για όλα τα κοντέινερ μαζί, για παράδειγμα όταν οι βάσεις σας κρατούν ήδη μόνες τους αντίγραφα. Ένα μεμονωμένο κοντέινερ κλείνει από την κάρτα του.",
