  "auth.resetCodeLabel": "Κωδικός από το αρχείο καταγραφής του container",
  "auth.resetCodeTip": "Το BombVault έγραψε έναν κωδικό στο αρχείο καταγραφής του container του. Στο Unraid: καρτέλα Docker, εικονίδιο BombVault, Logs. Ο κωδικός ισχύει για 10 λεπτά. Όποιος μπορεί να διαβάσει αυτό το αρχείο καταγραφής μπορεί να επαναφέρει τον κωδικό πρόσβασης, ακόμη και μέσω ενός προγράμματος προβολής αρχείων καταγραφής όπως το Dozzle. Η επαναφορά επίσης απενεργοποιεί την ταυτοποίηση δύο παραγόντων, αφαιρεί κάθε κλειδί πρόσβασης, ανακαλεί κάθε token API και κλειδί MCP, τερματίζει κάθε άλλη συνεδρία και σταματά τη σύζευξη τηλεφώνων μέχρι να την ενεργοποιήσετε ξανά.",
