  // Retention
  "excludes.advisoryImmichDb": "Το Immich κρατά τα άλμπουμ, τα πρόσωπα και τις ημερομηνίες κάθε φωτογραφίας σε μια βάση δεδομένων PostgreSQL που τρέχει σε δικό της, ξεχωριστό κοντέινερ, οπότε αυτό το αντίγραφο ασφαλείας δεν την περιέχει. Η επαναφορά από εδώ φέρνει πίσω τις φωτογραφίες, αλλά χωρίς τίποτα από αυτά. Το BombVault παίρνει dump εκείνου του κοντέινερ βάσης αυτόματα όταν αυτό μπαίνει σε αντίγραφο, οπότε ελέγξτε ότι περιλαμβάνεται στο πρόγραμμά σας.",
  "excludes.advisoryNextcloudDb": "Το Nextcloud κρατά τους λογαριασμούς, τους διαμοιρασμούς και τις ετικέτες του σε μια βάση δεδομένων που συνήθως τρέχει σε ξεχωριστό κοντέινερ, οπότε αυτό το αντίγραφο ασφαλείας δεν την περιέχει. Τα αρχεία επιστρέφουν, ο διαμοιρασμός όχι. Το BombVault παίρνει dump εκείνου του κοντέινερ βάσης αυτόματα όταν αυτό μπαίνει σε αντίγραφο, οπότε ελέγξτε ότι περιλαμβάνεται στο πρόγραμμά σας.",
