  "excludes.presetHint.previews": "Εικόνες προεπισκόπησης που δημιουργήθηκαν. Η εφαρμογή τις φτιάχνει ξανά μετά από επαναφορά, κάτι που σε μεγάλη βιβλιοθήκη μπορεί να πάρει ώρες.",
  "excludes.presetHint.trickplay": "Εικόνες για τη γραμμή αναπαραγωγής. Μια προγραμματισμένη εργασία τις φτιάχνει ξανά μετά από επαναφορά.",
  "excludes.presetHint.metadata": "Αφίσες και εικόνες που κατέβασε η εφαρμογή. Μια ανανέωση μεταδεδομένων τις φέρνει ξανά, αλλά εδώ βρίσκονται και εικόνες που ανεβάσατε εσείς, και αυτές θα χάνονταν. Αυτή η καταχώριση ξεκινά απενεργοποιημένη.",
