  "rcloneRemote.heading": "Προσθήκη προορισμού SMB ή WebDAV",
  "rcloneRemote.hint": "Συνδέεται σε κοινόχρηστο πόρο Windows ή Samba, ή σε διακομιστή WebDAV όπως το Nextcloud, χωρίς να τον προσαρτά στο host. Το restic δεν συνιστά την αποθήκευση αποθετηρίου σε προσαρτημένο κοινόχρηστο πόρο CIFS, και αυτός ο τρόπος αποφεύγει εντελώς την προσάρτηση. Ο κωδικός παραδίδεται στο rclone, που τον αποθηκεύει στη δική του μορφή, και δεν φυλάσσεται ποτέ σε απλό κείμενο. Το NFS δεν προσφέρεται εδώ, επειδή ούτε το restic ούτε το rclone το υποστηρίζουν: για NFS, προσαρτήστε το export στο Unraid και ορίστε μια διαδρομή αντιγράφων προς αυτό.",
