  "settings.retentionYearlyInfo": "Διατηρεί ένα αντίγραφο ασφαλείας για καθένα από τα τελευταία N ημερολογιακά έτη με αντίγραφο ασφαλείας. Αν τα έτη είναι λιγότερα, διατηρείται και το παλαιότερο.",
  "settings.retentionOffsiteTitle": "Διατήρηση εκτός τόπου",
  "settings.retentionOffsiteHint": "Ξεχωριστή πολιτική για το απομακρυσμένο repo, ώστε να το κρατάτε περισσότερο ως αρχείο. Όλα 0 = κρατιέται κάθε απομακρυσμένο αντίγραφο (χωρίς απομακρυσμένο κλάδεμα).",
  "settings.ownRetentionTitle": "Κανόνες διατήρησης ανά πηγή",
  "settings.ownOffsiteRetention": "Δικοί κανόνες διατήρησης εκτός τόπου",
  "settings.ownOffsiteRetentionFor": "Δικοί κανόνες διατήρησης εκτός τόπου για {source}",
  "settings.ownOffsiteRetentionHint": "Κάθε πηγή μπορεί να κρατά τα αντίγραφα στο απομακρυσμένο repo της με δικούς της κανόνες αντί για τους κοινούς απομακρυσμένους κανόνες παραπάνω. Μια πηγή χωρίς δικούς της κανόνες χρησιμοποιεί τους κοινούς.",
  "settings.ownOffsiteRetentionToggleHint": "Ενεργό: το απομακρυσμένο repo αυτής της πηγής κρατά τα αντίγραφά του με τους πέντε κανόνες παρακάτω, που ξεκινούν από τις κοινές απομακρυσμένες τιμές. Ανενεργό: χρησιμοποιεί τους κοινούς απομακρυσμένους κανόνες. Όλα 0 κρατά κάθε απομακρυσμένο αντίγραφο αυτής της πηγής.",
  "settings.retentionExtraTargets": "Οι πρόσθετοι απομακρυσμένοι προορισμοί κρατούν τους δικούς τους κανόνες, που ορίζετε στην κάρτα Αντίγραφο εκτός τόπου κάθε τομέα.",
  "settings.retentionOffsiteScope": "Αυτοί οι κανόνες ισχύουν για τον κύριο απομακρυσμένο προορισμό κάθε τομέα, δηλαδή τη διεύθυνση στο πεδίο εκτός τόπου. Κάθε άλλος απομακρυσμένος προορισμός, ακόμη και αυτός που προήλθε από έναν προορισμό, κρατά τους δικούς του κανόνες. Αν εκεί υπάρχουν μόνο μηδενικά, το BombVault δεν τον κλαδεύει ποτέ.",
  "settings.retentionCombineInfo": "Οι πέντε κανόνες συνδυάζονται με Ή: ένα αντίγραφο ασφαλείας επιβιώνει αν έστω ένας κανόνας το διατηρούσε. Δεν αθροίζονται σε σταθερό αριθμό. Ισχύει ξεχωριστά για κάθε στοιχείο που αντιγράφεται.",

  // Off-site (rclone)
  "rclone.title": "Εκτός τόπου (rclone)",
  "rclone.hint": "Επικολλήστε μια διαμόρφωση rclone για αντίγραφα στο cloud (Backblaze B2, S3, Google Drive, …). Αποθηκεύεται κρυπτογραφημένη. SMB/NFS δεν χρειάζονται rclone: προσαρτήστε τον κοινόχρηστο πόρο στο Unraid και ορίστε μια διαδρομή αντιγράφων προς αυτόν.",
  "rclone.configured": "Διαμορφωμένα remotes",
