  "dbdump.databasesLine": "Βάσεις δεδομένων: {names}",
  "dbdump.damagedBadge": "Χαλασμένο",
  "dbdump.damagedHint": "Αυτό το αντίγραφο δεν πέρασε τους ελέγχους του και δεν μπόρεσε να αφαιρεθεί αυτόματα. Δεν γίνεται ούτε να ληφθεί ούτε να εισαχθεί. Διαγράψτε το.",
  "dbdump.download": "Λήψη",
  "dbdump.format": "Μορφή αρχείου",
