  "dbdump.downloadRefused": "Η λήψη απορρίφθηκε",
  "dbdump.saveToFolder": "Αποθήκευση σε φάκελο",
  "dbdump.saveHint": "Γράφει το αντίγραφο ως αρχείο στον φάκελο που θα διαλέξετε στον διακομιστή, με ιδιοκτήτη nobody:users ώστε να το ανοίγετε μέσω του κοινόχρηστου δικτύου. Το αρχείο περιέχει κάθε πίνακα και τα hash των κωδικών των χρηστών της βάσης· φυλάξτε το εκεί όπου φτάνετε μόνο εσείς.",
  "dbdump.saveCancelHint": "Η ακύρωση σταματά την αποθήκευση και αφαιρεί το μισοτελειωμένο αρχείο.",
  "dbdump.savedTo": "Αποθηκεύτηκε στο {path}",
  "dbdump.import": "Εισαγωγή σε νέα βάση δεδομένων",
  "dbdump.importConfirm": "Να γίνει εισαγωγή αυτού του αντιγράφου {engine} {version} στο {container}; Το BombVault σταματά το κοντέινερ, παραμερίζει τον φάκελο δεδομένων του (μένει, δεν διαγράφεται τίποτα), ξεκινά το κοντέινερ με άδειο φάκελο δεδομένων και εισάγει το αντίγραφο. Οι εφαρμογές που χρησιμοποιούν αυτή τη βάση θα δουν την κατάστασή της τη στιγμή του αντιγράφου.",
  "dbdump.importConfirmNoVersion": "Να γίνει εισαγωγή αυτού του αντιγράφου {engine} στο {container}; Το BombVault σταματά το κοντέινερ, παραμερίζει τον φάκελο δεδομένων του (μένει, δεν διαγράφεται τίποτα), ξεκινά το κοντέινερ με άδειο φάκελο δεδομένων και εισάγει το αντίγραφο. Οι εφαρμογές που χρησιμοποιούν αυτή τη βάση θα δουν την κατάστασή της τη στιγμή του αντιγράφου.",
  "dbdump.importNoVersion": "Αυτό το αντίγραφο δεν καταγράφει την έκδοση της βάσης του. Η εισαγωγή αποτυγχάνει αν ο διακομιστής δεν μπορεί να το διαβάσει.",
  "dbdump.importStops": "one=Κατά την εισαγωγή το BombVault σταματά επίσης την {apps} και μετά την ξεκινά ξανά. Αν η εισαγωγή αποτύχει αφού έχει ξεκινήσει, τα παλιά δεδομένα μένουν στην άκρη και η εφαρμογή σταματημένη.|other=Κατά την εισαγωγή το BombVault σταματά επίσης αυτές τις εφαρμογές: {apps}. Μετά τις ξεκινά ξανά. Αν η εισαγωγή αποτύχει αφού έχει ξεκινήσει, τα παλιά δεδομένα μένουν στην άκρη και οι εφαρμογές σταματημένες.",
  "dbdump.importDone": "Η βάση δεδομένων εισήχθη.",
  "dbdump.importRefused.busy": "Τρέχει ήδη άλλο αντίγραφο ασφαλείας ή επαναφορά. Δοκιμάστε ξανά μόλις τελειώσει.",
  "dbdump.importRefused.notRunning": "Ξεκινήστε πρώτα το κοντέινερ· η εισαγωγή χρειάζεται τον διακομιστή σε λειτουργία.",
  "dbdump.importRefused.engineMismatch": "Αυτό το αντίγραφο προέρχεται από άλλον τύπο βάσης από αυτόν που τρέχει το κοντέινερ.",
  "dbdump.importRefused.noDataMount": "Το BombVault δεν φτάνει τον φάκελο δεδομένων αυτού του κοντέινερ, οπότε δεν μπορεί να τον παραμερίσει με ασφάλεια. Κάντε την εισαγωγή στο χέρι, όπως περιγράφει το πακέτο ανάκτησης.",
  "dbdump.importRefused.version": "Ο διακομιστής τρέχει την έκδοση {server}, το αντίγραφο προέρχεται από την {dump}. Χρησιμοποιήστε εικόνα με έκδοση {dump} ή νεότερη για αυτή την εισαγωγή.",
  "dbdump.importRefused.versionSameMajor": "Ο διακομιστής τρέχει την έκδοση {server}, το αντίγραφο προέρχεται από την {dump}. Η MySQL και η MariaDB εισάγουν ένα αντίγραφο μόνο στην κύρια έκδοση από την οποία προέρχεται, οπότε χρησιμοποιήστε εικόνα με έκδοση {dump} για αυτή την εισαγωγή.",
  "dbdump.importRefused.damaged": "Αυτό το αντίγραφο είναι χαλασμένο και δεν μπορεί να εισαχθεί.",
  "dbdump.importRefused.notADump": "Αυτό το αντίγραφο ασφαλείας δεν είναι αντίγραφο βάσης δεδομένων αυτού του κοντέινερ.",
  "dbdump.deleteConfirm": "Να διαγραφεί αυτό το αντίγραφο της βάσης δεδομένων; Αφαιρείται από το αποθετήριο (τρέξτε Prune στις Ρυθμίσεις για να ελευθερωθεί ο χώρος). Δεν αναιρείται.",
