  "offsite.wizard.tlsNote": "Αυτή η συνταγή χρησιμοποιεί απλό HTTP. Μια χαρά σε έμπιστο LAN ή VPN. Αν το storage box είναι προσβάσιμο μέσω internet, βάλτε τον rest-server πίσω από HTTPS (έναν αντίστροφο proxy με TLS), ώστε τα διαπιστευτήρια του αποθετηρίου να μην στέλνονται σε καθαρό κείμενο.",
  "offsite.wizard.password": "Παραγόμενος κωδικός (αποθηκεύστε τον)",
  "offsite.wizard.passwordInfo": "Ένα μυστικό σε δύο μορφές. Το απλό κείμενο παραπάνω πηγαίνει στο συνθηματικό REST αυτού του προορισμού, εδώ σε αυτό το μηχάνημα. Οι συνταγές παρακάτω φέρουν το ίδιο συνθηματικό ήδη κατακερματισμένο, στη γραμμή που προσθέτει στο .htpasswd, και αυτή η γραμμή πηγαίνει στο μηχάνημα αποθήκευσης. Δεν χρειάζεται να κατακερματίσετε τίποτα εσείς.",
