  "dest.groupTip.storage": "Buckets με πρόσβαση μέσω κλειδιού. Γρήγορα, οικονομικά ανά terabyte, και με object lock οι παλιές εκδόσεις διατηρούνται ακόμη κι αν κάποιος τις διαγράψει.",
  "dest.groupTip.selfs3": "Ένας διακομιστής S3 που τρέχει στο δικό σας υλικό, όπως ένα δεύτερο μηχάνημα Unraid στο σπίτι ενός συγγενή.",
  "dest.groupTip.server": "Ένα μηχάνημα που διαχειρίζεστε ή νοικιάζετε οι ίδιοι: ένα δεύτερο NAS, ένα Hetzner Storage Box, ένα Raspberry Pi κάπου αλλού.",
  "dest.groupTip.cloud": "Υπηρεσίες φτιαγμένες για έγγραφα και φωτογραφίες. Περιορίζουν τα πολλά αιτήματα, οπότε το πρώτο αντίγραφο και το κλάδεμα διαρκούν περισσότερο.",
  "dest.note.slower": "Λειτουργεί, αλλά πιο αργά. Το {name} περιορίζει τα πολλά αιτήματα, οπότε το πρώτο αντίγραφο και το κλάδεμα διαρκούν πολύ περισσότερο εδώ απ' ό,τι σε μια υπηρεσία αποθήκευσης.",
  "dest.note.dailyCap": "Το Google Drive δέχεται το πολύ 750 GB μεταφορτώσεων την ημέρα.",
  "dest.note.selfHosted": "Τρέχει στον δικό σας διακομιστή και είναι τόσο γρήγορο όσο η σύνδεσή του.",
  "dest.note.rest": "Η πρώτη επιλογή για εκτός τόπου αντίγραφα: ένα rest-server σε λειτουργία append-only αρνείται από μόνο του τη διαγραφή και το BombVault μπορεί να το ελέγξει.",
  "dest.note.good": "Κατάλληλο για αντίγραφα ασφαλείας.",
  "dest.note.lock": "Εδώ είναι δυνατή η προστασία από διαγραφή.",
  "dest.name": "Όνομα",
  "dest.nameHint": "Εμφανίζεται στα κουμπιά. Μπορεί να αλλάξει αργότερα.",
  "dest.token.run": "Εκτελέστε το σε υπολογιστή με πρόγραμμα περιήγησης και συνδεθείτε",
  "dest.token.tip": "Το BombVault τρέχει σε διακομιστή χωρίς πρόγραμμα περιήγησης. Το rclone ανοίγει τη σύνδεση στον υπολογιστή σας και εκτυπώνει στη συνέχεια ένα διακριτικό, που μπαίνει στο παρακάτω πεδίο. Το rclone για Windows, macOS και Linux υπάρχει στο rclone.org.",
  "dest.sshKey": "Προσθέστε το δημόσιο κλειδί SSH του BombVault στον διακομιστή",
  "dest.sshKey.tip": "Το ίδιο κλειδί που χρησιμοποιεί το BombVault για αντίγραφα VM μέσω SSH. Με το κλειδί στη θέση του δεν χρειάζεται κωδικός και η σύνδεση με κωδικό μπορεί να απενεργοποιηθεί στον διακομιστή.",
  "dest.appPassword.tip": "Με ενεργή τη σύνδεση δύο παραγόντων, ο κανονικός κωδικός δεν λειτουργεί. Δημιουργήστε έναν κωδικό εφαρμογής στις ρυθμίσεις ασφαλείας του λογαριασμού σας.",
  "dest.key.note": "Τα κλειδιά αποθηκεύονται κρυπτογραφημένα μαζί με τα υπόλοιπα διαπιστευτήρια cloud. Ένα κλειδί μόνο για αυτό το bucket είναι ασφαλέστερο από το κύριο κλειδί του λογαριασμού.",
