  "dest.route.s3": "Οι υπηρεσίες S3 χρησιμοποιούν το δικό του backend S3 του restic αντί για το rclone, και έτσι ισχύουν κλάση αποθήκευσης και object lock.",
  "dest.route.rclone": "Το restic φτάνει σε αυτή την υπηρεσία μέσω του rclone που περιλαμβάνει το BombVault. Το remote εμφανίζεται τότε στο rclone.conf στις Ρυθμίσεις, Προορισμοί.",
  "dest.route.rest": "Το restic μιλά απευθείας με το rest-server.",
  "dest.route.path": "Ένας φάκελος μέσα στην προσάρτηση δεδομένων του host.",
  "dest.lock.s3": "Ενεργοποιήστε το versioning και το object lock για το bucket. Οι παλιές εκδόσεις διατηρούνται τότε ακόμη κι αν κάποιος διαγράψει με το κλειδί. Το BombVault δεν μπορεί ακόμη να το ελέγξει για το {name}.",
  "dest.lock.none": "Το {name} δεν μπορεί να αρνηθεί τη διαγραφή. Όποιος μπαίνει στον διακομιστή σας μπαίνει και σε αυτό το αποθετήριο εκτός τόπου. Απέναντι στο ransomware βοηθά ένα rest-server ή μια υπηρεσία αποθήκευσης με object lock, για παράδειγμα ως δεύτερος προορισμός.",
  "dest.lock.rest": "Μετά την αποθήκευση, η δοκιμή παραβίασης στην κάρτα του τομέα ελέγχει ότι ο διακομιστής αρνείται τη διαγραφή.",
  "dest.recovery": "Το κιτ ανάκτησης αναφέρει αυτόν τον προορισμό μαζί με το αποθετήριο κάθε τομέα που βρίσκεται από κάτω. Η ίδια η σύνδεση επανέρχεται με το Αυτο-αντίγραφο του BombVault· χωρίς αυτό, εισάγεται ξανά στον νέο διακομιστή.",
  "dest.recovery.token": "Το {name} ανανεώνει συνεχώς την πρόσβαση, οπότε ένα διακριτικό από παλιότερο Αυτο-αντίγραφο μπορεί να έχει λήξει. Τότε συνδεθείτε ξανά μία φορά. Το ίδιο το αποθετήριο δεν επηρεάζεται.",
  "dest.recovery.ssh": "Το κλειδί SSH επανέρχεται επίσης με το Αυτο-αντίγραφο. Σε καθαρή εγκατάσταση χωρίς αυτό, το νέο κλειδί πρέπει να μπει στον διακομιστή.",
