  "offsite.prune.title": "5 · Κλάδεμα εκτός τόπου",
  "offsite.prune.info": "Αυτό το βήμα απλώς αναφέρει τι συμβαίνει, δεν ρυθμίζει τίποτα. Το αν κλαδεύεται αυτό το αντίγραφο το καθορίζουν το append-only στο βήμα 4 και οι τιμές διατήρησης στις Ρυθμίσεις, Προορισμοί. Για να κλαδέψετε παρ' όλα αυτά ένα αντίγραφο append-only, τρέξτε restic forget --prune στην πλευρά της αποθήκευσης, είτε με δικό του χρονοδιάγραμμα είτε σηκώνοντας για λίγο έναν δεύτερο διακομιστή REST χωρίς append-only, κλαδεύοντας μέσω αυτού και κλείνοντάς τον ξανά.",
  "offsite.prune.stateFarSide": "Από εδώ τίποτα δεν κλαδεύει αυτό το αντίγραφο. Το append-only είναι ενεργό, οπότε το BombVault μόνο προσθέτει σε αυτό, και το κλάδεμα είναι δουλειά της πλευράς αποθήκευσης.",
  "offsite.prune.statePolicy": "Το BombVault κλαδεύει αυτό το αντίγραφο μετά από κάθε αναπαραγωγή, σύμφωνα με την πολιτική απομακρυσμένης διατήρησης.",
  "offsite.prune.stateNone": "Τίποτα δεν κλαδεύει αυτό το αντίγραφο. Το append-only είναι ανενεργό και όλες οι απομακρυσμένες τιμές διατήρησης είναι 0, οπότε μεγαλώνει μέχρι να γεμίσει ο δίσκος.",
  "offsite.prune.effective": "Διατηρεί {last} πιο πρόσφατα, {daily} ημερήσια, {weekly} εβδομαδιαία, {monthly} μηνιαία, {yearly} ετήσια.",
  "offsite.prune.editedElsewhere": "Ορίζεται στις Ρυθμίσεις, Προορισμοί. Όλες οι πηγές μοιράζονται αυτές τις τιμές, εκτός αν μία έχει δικούς της κανόνες.",
  "offsite.prune.budgetInfo": "Σημαίνει συναγερμό μόλις το απομακρυσμένο αποθετήριο ξεπεράσει τόσα gigabyte. Δεν διαγράφει ποτέ τίποτα, οπότε είναι το δίχτυ ασφαλείας για ένα αντίγραφο που δεν το κλαδεύει τίποτα.",
  "settings.retentionImmutableNotPruned": "Ένας απομακρυσμένος προορισμός με append-only δεν κλαδεύεται ποτέ από εδώ, ό,τι κι αν λένε αυτές οι τιμές. Το δικό του βήμα στον απομακρυσμένο οδηγό εξηγεί πώς να τον κλαδέψετε από την πλευρά της αποθήκευσης.",

