  "zfs.safety.old": "Το παλαιότερο στιγμιότυπο ασφαλείας είναι πάνω από 30 ημερών. Κρατά διαγραμμένα και αλλαγμένα δεδομένα στο pool μέχρι να το σβήσετε.",
  "zfs.safety.hint": "Το BombVault πήρε αυτά τα στιγμιότυπα λίγο πριν από μια επαναφορά μέσα σε σύνολο δεδομένων, ώστε η προηγούμενη κατάσταση να μπορεί να γυρίσει πίσω. Το BombVault δεν τα σβήνει ποτέ μόνο του. Μεμονωμένα αρχεία τα παίρνεις πίσω αντιγράφοντάς τα από το .zfs/snapshot/<name> μέσα στο σύνολο δεδομένων. Το zfs rollback δουλεύει μόνο όσο είναι το νεότερο στιγμιότυπο εκείνου του συνόλου: το zfs rollback -r σβήνει κάθε νεότερο στιγμιότυπο, και τα αυτόματα.",
