  "zfs.deleteBackupsConfirm": "Να σβηστούν όλα τα αντίγραφα αυτού του στοιχείου και των συνόλων δεδομένων του; Τα αντίγραφα φεύγουν οριστικά, το αποθετήριο καθαρίζεται και το στοιχείο βγαίνει από τη λίστα. Αυτό δεν αναιρείται.",
