  "zfs.replica.title": "Ρεπλίκα",
  "zfs.replica.hint": "Η ρεπλίκα είναι ένα πανομοιότυπο, μπλοκ προς μπλοκ, αντίγραφο των συνόλων δεδομένων σε έναν δεύτερο διακομιστή ZFS, που μπορείτε να συνδέσετε εκεί αμέσως. Μετά την πρώτη εκτέλεση το BombVault στέλνει μόνο τα μπλοκ που άλλαξαν. Οι παλαιότερες εκδόσεις, τα μεμονωμένα αρχεία και ο έλεγχος εξακολουθούν να προέρχονται από τα αντίγραφα ασφαλείας, οπότε η ρεπλίκα δεν τα αντικαθιστά.",
