  "recovery.abTitle": "Εισαγωγή από το πρόσθετο Appdata.Backup",
  "recovery.abIntro": "Κάνει τα αρχεία που έγραψε το πρόσθετο Appdata.Backup σημεία επαναφοράς των αντίστοιχων container, το καθένα με την ημερομηνία που το δημιούργησε το πρόσθετο. Τα αρχεία μόνο διαβάζονται, ποτέ δεν αλλάζουν ούτε διαγράφονται. Κάθε αρχείο αποσυμπιέζεται δίπλα στο αποθετήριο, αποθηκεύεται και το αποσυμπιεσμένο αντίγραφο διαγράφεται ξανά, οπότε εκεί χρειάζεται χώρος για το μεγαλύτερο αρχείο.",
