  "mcp.hint": "Επιτρέπει σε βοηθούς τεχνητής νοημοσύνης όπως το Claude να διαβάζουν την κατάσταση των αντιγράφων αυτού του διακομιστή, να ξεκινούν αντίγραφα και να ακυρώνουν όσα ξεκίνησαν οι ίδιοι, μέσω του Model Context Protocol. Οι επαναφορές, οι διαγραφές και οι ρυθμίσεις μένουν σε αυτή τη διεπαφή.",
