  "mcp.stepOAuth": "Ενεργοποίηση σύνδεσης",
  "mcp.setupChatGPT": "Στο ChatGPT ανοίξτε Ρυθμίσεις, Εφαρμογές και σύνδεσμοι και ενεργοποιήστε τη λειτουργία προγραμματιστή στις Ρυθμίσεις για προχωρημένους. Μετά επιλέξτε Δημιουργία, δώστε όνομα στον σύνδεσμο, επικολλήστε το URL συνδέσμου ως URL διακομιστή MCP, επιλέξτε OAuth ως έλεγχο ταυτότητας, επιβεβαιώστε ότι τον εμπιστεύεστε και δημιουργήστε τον.",
  "mcp.setupClaudeAi": "Στο claude.ai ανοίξτε Ρυθμίσεις, Σύνδεσμοι και επιλέξτε Προσθήκη προσαρμοσμένου συνδέσμου. Δώστε του όνομα, επικολλήστε το URL συνδέσμου, αφήστε κενά το αναγνωριστικό πελάτη και το μυστικό OAuth και προσθέστε τον. Μετά επιλέξτε Σύνδεση.",
