  "mcp.oauthProxyNote": "Η υπηρεσία καλεί τα /mcp, /oauth/ και /.well-known/ από τους δικούς της διακομιστές, οπότε ένας αντίστροφος διακομιστής μεσολάβησης με δική του σύνδεση πρέπει να αφήνει αυτές τις διαδρομές να φτάνουν στο BombVault.",
