  "mcp.notePerplexity": "Προς το παρόν μόνο η εφαρμογή Mac του Perplexity συνδέεται με διακομιστές MCP στον υπολογιστή ή στο δίκτυό σας· η εφαρμογή Windows και ο ιστότοπος όχι.",
  "mcp.noteGrok": "Η τεκμηρίωση του Grok δεν δείχνει αναλυτικά τη φόρμα συνδέσμων του. Αν προσφέρει μόνο σύνδεση και κανένα πεδίο για κεφαλίδα, δεν μπορεί ακόμη να χρησιμοποιήσει κλειδί BombVault.",
  "mcp.certNotForThisAddress": "Το πιστοποιητικό του BombVault δεν αναφέρει το {host}, οπότε οι βοηθοί θα αρνηθούν να συνδεθούν σε αυτή τη διεύθυνση. Προσθέστε τη διεύθυνση στο πιστοποιητικό και μετά κατεβάστε το για τα αποσπάσματα.",
