  "api.title": "Tokens API",
  "api.hint": "Tokens για σενάρια, πίνακες ελέγχου και οικιακό αυτοματισμό. Ένα token ανοίγει το API κάτω από το /api/v1 και τίποτε άλλο. Οι επαναφορές, οι διαγραφές και οι ρυθμίσεις μένουν σε αυτή τη διεπαφή.",
  "api.addressLabel": "Διεύθυνση API",
