  "api.needsPasswordForHost": "Αυτή η σελίδα άνοιξε ως {host}. Χωρίς κωδικό εισόδου, tokens δημιουργούνται και αντικαθίστανται μόνο από διεύθυνση IP ή τοπικό όνομα όπως tower ή tower.local. Ορίστε κωδικό εισόδου ή ανοίξτε το BombVault από την τοπική του διεύθυνση.",
  "api.labelLabel": "Όνομα του token",
  "api.labelPlaceholder": "Νυχτερινό σενάριο κατάστασης",
  "api.allowStartHint": "Με αυτό ενεργό, το token μπορεί να ξεκινήσει αντίγραφο ενός στοιχείου, ενός ολόκληρου τομέα ή του πλήρους αντιγράφου ασφαλείας και να ακυρώσει όσα ξεκίνησε: το πολύ {n} την ώρα, με {minutes} λεπτά απόσταση για το ίδιο στοιχείο και {perDay} ανά στοιχείο την ημέρα. Ένα αντίγραφο σταματά τα container που τρέχουν μέχρι να τελειώσει. Χωρίς αυτό, το token μόνο διαβάζει.",
