  "instances.role.diff": "Με δέκτη, αυτός ο διακομιστής στέλνει: μετά από κάθε αντίγραφο ασφαλείας τοποθετεί ο ίδιος το αντίγραφό του εκτός τόπου στην άλλη εγκατάσταση, και εκείνη δεν αφήνει να διαγραφεί τίποτα εκεί. Με αντλητή, η άλλη εγκατάσταση αντλεί: διαβάζει τα αντίγραφα ασφαλείας αυτού του διακομιστή με δικό της πρόγραμμα, και αυτός ο διακομιστής δεν γνωρίζει ούτε τον προορισμό της ούτε τα διαπιστευτήριά της. Ο διακομιστής ZFS δέχεται ρεπλίκες ZFS, δηλαδή ακριβή αντίγραφα των datasets block προς block και όχι αντίγραφα ασφαλείας.",
  "instances.role.receiverTip": "Φυλάσσει τα αντίγραφα αυτού του διακομιστή εκτός τόπου σε ένα rest-server σε λειτουργία append-only. Αυτός ο διακομιστής δεν μπορεί να διαγράψει τίποτα εκεί, ακόμη κι αν κάποιος τον αναλάβει.",
  "instances.role.fetcherTip": "Αντλεί τα αντίγραφα ασφαλείας αυτού του διακομιστή με δικό του πρόγραμμα. Αυτός ο διακομιστής δεν χρειάζεται να είναι ξύπνιος γι' αυτό.",
  "instances.role.zfsTip": "Δέχεται τις ρεπλίκες ZFS αυτού του διακομιστή. Ποιο στοιχείο ZFS αντιγράφεται εκεί, το επιλέγετε στις ρυθμίσεις του, στο Ρεπλίκα.",
