  "relay.instanceName": "Εγκατάσταση BombVault",
  "relay.instanceSub": "Οποιαδήποτε συνδεδεμένη εγκατάσταση μπορεί να λειτουργήσει ως αναμεταδότης, εφόσον είναι προσβάσιμη από έξω.",
  "relay.serve": "Λειτουργία ως αναμεταδότης",
  "relay.serveHint": "Ενεργοποιήστε αυτό στην εγκατάσταση που είναι προσβάσιμη από έξω. Τότε απαντά στις άλλες εγκαταστάσεις της ομάδας σας στο /relay/connect στη δική της διεύθυνση.",
  "relay.serveClients": "one={n} εγκατάσταση συνδεδεμένη αυτή τη στιγμή|other={n} εγκαταστάσεις συνδεδεμένες αυτή τη στιγμή",
  "relay.instanceCert": "Ο αναμεταδότης τότε λειτουργεί στο /relay/connect στη διεύθυνσή της, πίσω από τον ίδιο reverse proxy και πιστοποιητικό.",
  "relay.instanceCertTip": "Δεν χρειάζεται δικό του πιστοποιητικό. Ό,τι κάνει την εγκατάστασή σας προσβάσιμη από έξω αρκεί και για τον αναμεταδότη.",
  "relay.addressLabel": "Η διεύθυνση του αναμεταδότη σας",
  "relay.addressTip": "Αυτή η διεύθυνση ισχύει μόνο για αυτή την εγκατάσταση. Εισαγάγετέ την σε κάθε εγκατάσταση που πρέπει να είναι προσβάσιμη μέσω του αναμεταδότη σας.",
  "relay.plaintextWarning": "Αυτή η διεύθυνση δεν έχει TLS, οπότε το κλειδί του αναμεταδότη διασχίζει το δίκτυο ως απλό κείμενο. Όποιος βρίσκεται στη διαδρομή μπορεί να το διαβάσει και να μπει στην ομάδα σας στον αναμεταδότη. Δεν μπορεί να διαβάσει τι στέλνουν μεταξύ τους οι εγκαταστάσεις σας, αλλά βλέπει ποιες εγκαταστάσεις επικοινωνούν και πότε. Χρησιμοποιήστε το μόνο σε δίκτυο που εμπιστεύεστε.",
  "relay.diagramRelay": "Αναμεταδότης",
  "relay.diagramYourNetwork": "Το δίκτυό σας",
  "relay.diagramOtherNetwork": "Άλλο δίκτυο",
  "relay.e2e": "Σε κάθε διαδρομή, όλα είναι κρυπτογραφημένα από άκρο σε άκρο. Όποιος λειτουργεί τον αναμεταδότη, το έργο ή εσείς, δεν μπορεί να διαβάσει τίποτα από αυτά.",
  "relay.e2eTip": "Το κλειδί προέρχεται από τις δώδεκα λέξεις και παραμένει στις εγκαταστάσεις σας. Ο αναμεταδότης βλέπει μόνο για ποια εγκατάσταση είναι ένα μήνυμα, πόσο μεγάλο είναι και πότε φτάνει. Αυτό δεν μπορεί να κρυπτογραφηθεί μακριά. Αν αυτό σας ενοχλεί, λειτουργήστε τον δικό σας αναμεταδότη.",
  "relay.notSeesContent": "Ό,τι στέλνουν οι εγκαταστάσεις σας μεταξύ τους. Είναι κρυπτογραφημένο από άκρο σε άκρο.",
  "relay.notSeesBackups": "Τα αντίγραφα ασφαλείας σας. Μέσω του αναμεταδότη περνούν μόνο η κατάσταση, οι εντολές και η σύζευξη.",
  "relay.saveError": "Δεν ήταν δυνατή η αποθήκευση της ρύθμισης του αναμεταδότη.",
  "pairing.knownAddresses": "Γνωστές διευθύνσεις",
  "pairing.foundAddresses": "Βρέθηκαν από αυτό το στιγμιότυπο",
  "relay.selfAddressTip": "Λαμβάνεται από το πρόγραμμα περιήγησής σας όταν συνδέεστε. Αλλάξτε την αν ένας reverse proxy ή διαφορετική θύρα παρεμβάλλεται ανάμεσα στο πρόγραμμα περιήγησής σας και αυτή την εγκατάσταση.",
  "relay.selfAddressError": "Δεν ήταν δυνατή η αποθήκευση της διεύθυνσης αυτής της εγκατάστασης.",
  "relay.sees.title": "Τι βλέπει ο αναμεταδότης",
  "relay.ownRuns": "Ο αναμεταδότης τρέχει ως κοντέινερ ParleyPort στο δικό σας περιβάλλον και τα στιγμιότυπά σας συνδέονται μέσω της διεύθυνσής του.",
  "relay.ownNeed": "Ένα κοντέινερ ParleyPort, προσβάσιμο απ' έξω.",
  "relay.instanceNeed": "Ένα στιγμιότυπο της ομάδας σας, προσβάσιμο απ' έξω.",
  "relay.containerAlso": "Το κοντέινερ υπάρχει και στις Ρυθμίσεις › Εφαρμογές.",
  "relay.pic.selfHosted": "Αυτο-φιλοξενία",
  "relay.pic.direct": "Δύο BombVault στο ίδιο δίκτυο μιλούν απευθείας. Ένα τρίτο σε άλλο δίκτυο δεν μπορεί να προσεγγιστεί χωρίς αναμεταδότη.",
  "relay.pic.instance": "Ένα BombVault είναι το ίδιο ο αναμεταδότης και περνά τα μηνύματα στο στιγμιότυπο του άλλου δικτύου. Τα κλειδιά τα έχουν μόνο τα δύο στιγμιότυπα.",
  "relay.pic.relay": "Δύο στιγμιότυπα σε διαφορετικά δίκτυα μιλούν μέσω του αναμεταδότη. Τα κλειδιά τα έχουν μόνο τα δύο στιγμιότυπα.",
