  "receiver.checkNever": "Δεν έχει ελεγχθεί ακόμη",
  "receiver.checkFailedHelp":
    "Το BombVault μόνο διαβάζει ένα αποθετήριο που έχει λάβει, οπότε δεν θα το επιδιορθώσει για εσάς. Για να το επιδιορθώσετε μόνοι σας, τρέξτε restic στην παραπάνω τοποθεσία με τον κωδικό που παράγεται από το APP_KEY της αποστέλλουσας εγκατάστασης, ο οποίος βρίσκεται στο κιτ ανάκτησης εκείνης της εγκατάστασης και όχι αυτού του μηχανήματος. Δοκιμάστε πρώτα `restic repair index` και μετά `restic repair snapshots` αν τα στιγμιότυπα εξακολουθούν να μη διαβάζονται.",
  "receiver.lastChecked": "Τελευταίος έλεγχος {time}",
  "receiver.server.title": "Διακομιστής λήψης",
  "receiver.server.tip": "Ένας rest-server σε λειτουργία append-only σε αυτό το μηχάνημα. Οι άλλες εγκαταστάσεις της ομάδας σας μπορούν να αντιγράφουν εκεί τα εξωτερικά αντίγραφα ασφαλείας τους, και ούτε όποιος κατέχει τη σύνδεσή τους μπορεί να διαγράψει ό,τι έχει φτάσει.",
  "receiver.server.intro": "Αφήστε τους συνεργάτες σας να αντιγράφουν τα εξωτερικά αντίγραφα ασφαλείας τους σε αυτό το μηχάνημα. Το BombVault ξεκινά εδώ έναν rest-server σε λειτουργία append-only και τον προσφέρει στις εγκαταστάσεις της ομάδας σας.",
  "receiver.server.setUp": "Ρύθμιση διακομιστή λήψης",
  "receiver.server.formIntro": "Το BombVault δημιουργεί ένα κοντέινερ rest-server σε λειτουργία append-only, το ξεκινά και ελέγχει ότι αρνείται τις διαγραφές. Κάθε εγκατάσταση της ομάδας σας παίρνει δική της σύνδεση όταν διαλέγει τον διακομιστή.",
  "receiver.server.folder": "Φάκελος για τις αποθήκες",
  "receiver.server.folderTip": "Τα αντίγραφα ασφαλείας που στέλνουν οι συνεργάτες σας καταλήγουν εδώ, δίπλα στο αρχείο συνδέσεων του διακομιστή. Διαλέξτε ένα share με άφθονο χώρο.",
  "receiver.server.port": "Θύρα",
  "receiver.server.portTip": "Η θύρα σε αυτό το μηχάνημα στην οποία ακούει ο διακομιστής. Κρατήστε το 8000, εκτός αν το χρησιμοποιεί άλλο κοντέινερ.",
  "receiver.server.host": "Διεύθυνση για τους συνεργάτες (προαιρετικό)",
  "receiver.server.hostTip": "Αφήστε το κενό και οι συνεργάτες σας χρησιμοποιούν τη διεύθυνση με την οποία φτάνουν ήδη σε αυτό το BombVault. Συμπληρώστε το όταν το BombVault έχει δική του διεύθυνση IP, για παράδειγμα στο br0, επειδή ο διακομιστής ακούει στη διεύθυνση του host.",
  "receiver.server.hostPlaceholder": "ίδια με αυτό το BombVault",
