  "receiver.server.password": "Κωδικός για αυτή τη σύνδεση, εμφανίζεται μόνο τώρα",
  "receiver.server.passwordTip": "Αυτή η σύνδεση προορίζεται για κάποιον εκτός της ομάδας σας, που την πληκτρολογεί χειροκίνητα. Αντιγράψτε την τώρα, γιατί δεν εμφανίζεται ξανά.",
  "receiver.server.templateWritten": "Το πρότυπο Unraid αποθηκεύτηκε, ώστε το κοντέινερ να επεξεργάζεται από την καρτέλα Docker.",
  "receiver.server.templateDownload": "Το BombVault δεν μπόρεσε να αποθηκεύσει το πρότυπο Unraid στη μονάδα flash. Κατεβάστε το και αντιγράψτε το στον φάκελο templates-user, δίπλα στα άλλα πρότυπα κοντέινερ του Unraid, και το κοντέινερ γίνεται επεξεργάσιμο από την καρτέλα Docker.",
