  "receiver.server.forgetAsk": "Να σταματήσει η προσφορά αυτού του διακομιστή λήψης στην ομάδα σας; Το κοντέινερ και τα αντίγραφα ασφαλείας στον φάκελό του μένουν, όπως και οι συνδέσεις που έχουν ήδη δοθεί. Εξαφανίζονται όμως από αυτή τη λίστα και δεν μπορούν πια να ανακληθούν από εδώ.",
