  "anomaly.title": "Ανωμαλίες",
  "anomaly.cardHint": "Το BombVault συγκρίνει κάθε αντίγραφο ασφαλείας ενός στοιχείου με τα προηγούμενα και ονομάζει ό,τι δεν ταιριάζει: πολύ περισσότερα νέα δεδομένα από το συνηθισμένο, επανεγγραφή των περισσότερων δεδομένων, πηγή που συρρικνώθηκε ή μεγάλωσε απότομα, μικρότερο αντίγραφο βάσης δεδομένων, αντίγραφο που ξαφνικά διαρκεί πολύ περισσότερο, επαναλαμβανόμενες αποτυχίες, έλεγχο επαναφοράς που δεν περνά πια, και δίσκο που σύντομα θα γεμίσει. Οι περισσότεροι έλεγχοι χρειάζονται πρώτα 10 αντίγραφα ενός στοιχείου. Ένα στοιχείο ZFS ελέγχεται ανά σύνολο δεδομένων, ώστε ένα θυγατρικό σύνολο που άδειασε να φαίνεται ακόμη και σε μεγάλο δέντρο.",
