  "anomaly.sentence.newDataRewrite": "Το {name} ξαναέγραψε {bytes} σε ένα αντίγραφο, τουλάχιστον τα μισά από όσα φυλάσσει ({source}). Αν δεν αλλάξατε τόσα, ελέγξτε αν τα αρχεία κρυπτογραφήθηκαν ή αντικαταστάθηκαν.",
