  "anomaly.learn.title": "Πρόοδος εκμάθησης",
  "anomaly.learn.hint": "Κάθε στοιχείο που αντιγράφεται δείχνει την πρόοδο εκμάθησής του σε έναν δακτύλιο δέκα τμημάτων, ένα για κάθε αντίγραφο από το οποίο έμαθε το BombVault. Ένας γεμάτος πράσινος δακτύλιος σημαίνει ότι το στοιχείο ολοκλήρωσε την εκμάθηση. Κάντε κλικ σε ένα για να ανοίξετε την παρακολούθησή του με τις συνήθεις τιμές και τη δική του ευαισθησία.",
