  "anomaly.runBadge": "Ανωμαλία",
  "anomaly.snapshotFlagged": "Σημειωμένο ως ανωμαλία",
  "anomaly.prunePaused": "Ο καθαρισμός έγινε. Τα παλιά αντίγραφα διατηρήθηκαν για στοιχεία με ανοιχτή ανωμαλία: {names}",
  "anomaly.settings.title": "Ανωμαλίες",
  "anomaly.settings.hint": "Συγκρίνει κάθε αντίγραφο ενός στοιχείου με το δικό του ιστορικό και αναφέρει ό,τι δεν ταιριάζει. Τρέχει στο παρασκήνιο μετά από κάθε αντίγραφο και δεν καθυστερεί κανένα. Οι περισσότεροι έλεγχοι ξεκινούν μετά από 10 αντίγραφα ενός στοιχείου· οι αποτυχίες, η επανεγγραφή των περισσότερων δεδομένων και μια σχεδόν άδεια πηγή ελέγχονται από την αρχή. Ο ελεύθερος χώρος παρακολουθείται για τοπικά αποθετήρια και για αποθετήρια rclone που τον αναφέρουν· στο κοινόχρηστο χρήστη του Unraid είναι ο ελεύθερος χώρος ολόκληρης της συστοιχίας.",
  "anomaly.settings.toggle": "Εντοπισμός ανωμαλιών",
  "anomaly.settings.sensitivity": "Ευαισθησία",
  "anomaly.settings.sensitivityHint": "Η Αυστηρή αναφέρει και μικρότερες αλλαγές, η Επιεικής μόνο μεγάλες, η Ισορροπημένη ταιριάζει στους περισσότερους διακομιστές. Κάθε στοιχείο μπορεί να έχει δική του ρύθμιση στις Ανωμαλίες, Παρακολούθηση.",
  "anomaly.settings.notifyMin": "Αποστολή ειδοποίησης για",
  "anomaly.settings.notifyHint": "Χρησιμοποιεί τα κανάλια που έχουν ρυθμιστεί στις Ειδοποιήσεις. Κάθε στοιχείο μπορεί να το αλλάξει στις Ανωμαλίες, Παρακολούθηση. Οι επαναλαμβανόμενες αποτυχίες αντιγράφων και αντιγράφων βάσης και οι αποτυχημένοι προγραμματισμένοι έλεγχοι επαναφοράς στέλνουν ήδη δικό τους μήνυμα, οπότε δεν στέλνονται δεύτερη φορά.",
  "anomaly.settings.notifyMuted": "Αυτή τη στιγμή δεν αποστέλλεται τίποτα: οι ειδοποιήσεις είναι απενεργοποιημένες ή δεν έχει ρυθμιστεί κανάλι.",
  "anomaly.settings.openNotifications": "Άνοιγμα ρυθμίσεων ειδοποιήσεων",
  "anomaly.settings.holdToggle": "Διατήρηση παλιών αντιγράφων όταν μια πηγή συρρικνώνεται απότομα ή ξαναγράφεται",
  "anomaly.settings.holdHint": "Τρία ευρήματα σταματούν τη διαγραφή παλιών αντιγράφων: μια πηγή που ξαφνικά είναι σχεδόν άδεια, μια που έγινε πολύ μικρότερη και ένα αντίγραφο που αποθήκευσε ξανά τα περισσότερα δεδομένα, όπως φαίνεται ένα ransomware. Η διατήρηση θα έσβηνε αλλιώς τα καλά παλαιότερα αντίγραφα ένα ένα. Όσο μια τέτοια ανωμαλία είναι ανοιχτή, διατηρούνται τα παλιά αντίγραφα μόνο εκείνου του στοιχείου (ή εκείνου του αντιγράφου βάσης δεδομένων ή συνόλου δεδομένων ZFS)· όλα τα άλλα καθαρίζονται κανονικά. Επιβεβαιώστε την ανωμαλία ή σημειώστε την ως αναμενόμενη για να συνεχιστεί.",
