  "storage.flow.hint": "Η προεπιλογή για κάθε τομέα. Στο γράφημα κάθε γραμμή είναι ένα αντίγραφο, και με κλικ σε μια γραμμή ή σε μια κουκκίδα την ενεργοποιείτε ή την απενεργοποιείτε. Οι διακεκομμένες γραμμές είναι ανενεργές. Στους «Διακόπτες» ρυθμίζετε το ίδιο με κουμπιά. Τα στοιχεία που ακολουθούν την προεπιλογή παίρνουν αμέσως μια αλλαγή από εδώ· όσα έχουν επιλέξει δικούς τους προορισμούς στη σελίδα τους τους κρατούν. Τους δικούς του κανόνες ένας τομέας, όπως διατήρηση, συμπίεση ή δική του διεύθυνση, τους ρυθμίζετε στη σελίδα του προορισμού.",
