  "welcome.restoreHint": "Έχετε ξαναχρησιμοποιήσει το BombVault; Τότε η «Επαναφορά από αντίγραφο ασφαλείας» επαναφέρει τα πάντα, μαζί με τις ρυθμίσεις.",
  "whatsNew.title": "Νέα",
