  "whatsNew.page.entry": "Σελίδα ενός στοιχείου",
  "whatsNew.page.location": "Σελίδα ενός προορισμού",
  "whatsNew.overviewHead": "Οι πράσινες κουκκίδες δείχνουν τι είναι καινούργιο. Ένα κλικ κρύβει μια κουκκίδα, και στις Ρυθμίσεις, Πληροφορίες θα βρείτε όλες.",
  "whatsNew.overviewCustomize": "Η επισκόπηση ξεκινά με πέντε κάρτες. Περισσότερες περιμένουν στην «Προσαρμογή», και κάθε κάρτα μπορεί να μετακινηθεί, να αλλάξει μέγεθος και να κρυφτεί.",
  "whatsNew.overviewDecline": "Το «Μη δημιουργία αντιγράφου» βγάζει ένα στοιχείο από αυτή τη λίστα, όταν το αφήνετε έξω επίτηδες. Τότε δεν μετράει πια ως μη προστατευμένο.",
  "whatsNew.backupsTiles": "Ό,τι αντιγράφεται βρίσκεται σε μία λίστα. Τα πλακίδια επιλέγουν ένα είδος.",
  "whatsNew.backupsBar": "Τα «Φίλτρα», η «Ταξινόμηση» και η «Αναζήτηση» είναι τρία κουμπιά πάνω από τη λίστα.",
  "whatsNew.backupsRow": "Μια γραμμή δείχνει μία κατάσταση και τα υπόλοιπα βρίσκονται στο συννεφάκι δίπλα στο όνομα. Επιλέξτε γραμμές όπως αρχεία: Ctrl+κλικ, Shift+κλικ ή παρατεταμένο πάτημα.",
  "whatsNew.backupsActions": "Η κύρια ενέργεια μιας σελίδας αιωρείται κάτω δεξιά. Τις σπάνιες τις κρύβουν τα «Περισσότερα».",
  "whatsNew.entryPage": "Κάθε στοιχείο έχει τη δική του σελίδα με τρεις καρτέλες: Αντίγραφα ασφαλείας, Ρυθμίσεις και Επαλήθευση.",
  "whatsNew.entryDefaults": "Ένα στοιχείο ακολουθεί το προεπιλεγμένο χρονοδιάγραμμα και προορισμό, μέχρι να αποκτήσει δικά του εδώ.",
  "whatsNew.restoreTiles": "Η «Επαναφορά» είναι μία σελίδα για όλα. Διαλέξτε έναν τομέα ή αναζητήστε ένα στοιχείο και μετά επιλέξτε ένα αντίγραφο ασφαλείας στη χρονική του γραμμή.",
  "whatsNew.restoreWhere": "Ένα παράθυρο ρωτά τι θα επαναφερθεί και πού. Το «Δίπλα στο πρωτότυπο» επαναφέρει ένα αντίγραφο και αφήνει το πρωτότυπο ως έχει.",
  "whatsNew.restoreMany": "Επιλέξτε πολλά στοιχεία με Ctrl+κλικ, Shift+κλικ ή παρατεταμένο πάτημα και επαναφέρετέ τα μαζί, το ένα μετά το άλλο.",
  "whatsNew.restoreEmergency": "Από εδώ ξεκινά ο οδηγός έκτακτης ανάγκης. Επαναφέρει έναν διακομιστή που χάθηκε ή στήθηκε ξανά, σε τέσσερα βήματα.",
  "whatsNew.anomaliesTiles": "Τα πλακίδια επιλέγουν τη σοβαρότητα. Με «Ανοιχτή» ή «Κλειστή» επιλέγετε τη λίστα.",
  "whatsNew.anomaliesRings": "Ένας δακτύλιος ανά στοιχείο δείχνει πόσο έχει μάθει η ανίχνευση τι είναι φυσιολογικό.",
  "whatsNew.storageList": "Οι τοπικοί και οι εξωτερικοί προορισμοί βρίσκονται σε μία λίστα. Κάθε προορισμός έχει τη δική του σελίδα.",
  "whatsNew.storageFlow": "Το 3-2-1 ως εικόνα. Κάθε γραμμή από έναν τομέα σε έναν προορισμό είναι ένας διακόπτης.",
  "whatsNew.locationKeep": "Η διατήρηση είναι «Σύντομη», «Ισορροπημένη», «Μεγάλη» ή δικές σας τιμές. Η χρονική γραμμή δείχνει ποια αντίγραφα ασφαλείας κρατά ένας κανόνας.",
  "whatsNew.locationMove": "Η «Μετακίνηση» μεταφέρει το αντίγραφο ενός τομέα σε άλλον προορισμό, μαζί με όλο το ιστορικό του.",
  "whatsNew.instancesPair": "Τα στιγμιότυπα συζεύγνυνται με δώδεκα λέξεις. Έπειτα το καθένα δείχνει τους ρόλους του ως πλακίδια.",
  "whatsNew.settingsTiles": "Οι ρυθμίσεις είναι δεκατέσσερα πλακίδια. Πατήστε / ή Ctrl+K για να τις αναζητήσετε όλες, ακόμη και με τα ονόματα που είχαν παλιότερα οι σελίδες.",
  "whatsNew.settingsPin": "Οι Προορισμοί και τα Στιγμιότυπα είναι πλακίδια των ρυθμίσεων. Αυτός ο διακόπτης τα καρφιτσώνει στην πλαϊνή μπάρα.",
